class PaymentProcessor:
    def __init__(self, security_code):
        self.security_code = security_code

    def process_debit(self):
        print("Processing debit payment type")
        print(f"Verifying security code: {self.security_code}")

    def process_credit(self):
        print("Processing credit payment type")
        print(f"Verifying security code: {self.security_code}")

class Order:
    def __init__(self):
        self.items = []
        self.quantities = []
        self.prices = []
        self.status = "open"

    def add_item(self, name: str, quantity: int, price: float) -> None:
        self.items.append(name)
        self.quantities.append(quantity)
        self.prices.append(price)

    def total_price(self):
        total = 0
        for quantity, price in zip(self.quantities, self.prices):
            total += quantity * price
        return total

    def pay(self, payment_type: str, processor: PaymentProcessor):
        if payment_type == "debit":
            processor.process_debit()
            self.status = "paid"
        elif payment_type == "credit":
            processor.process_credit()
            self.status = "paid"
        else:
            raise Exception(f"Unknown payment type: {payment_type}")


order = Order()
order.add_item("Keyboard", 1, 50)
order.add_item("SSD", 1, 150)
order.add_item("USB cable", 2, 5)
print(order.total_price())
processor = PaymentProcessor("0372846")
order.pay("debit", processor)
